operation.add:
{% set stripe_key = config.get('payment_stripe_applepay_publishable_key') %}
{% set stripe_enabled = config.get('payment_stripe_applepay_status') %}
{% set stripe_button_enabled = config.get('payment_stripe_applepay_product_button') %}
{% if stripe_enabled and stripe_button_enabled and stripe_key %}
<meta name="stripe-publishable-key" content="{{ stripe_key }}">
<script src="https://js.stripe.com/v3/"></script>
<script src="catalog/view/javascript/stripe_applepay.js"></script>
<script>
// Initialize Stripe Apple Pay on product page
if (typeof StripeProductApplePay !== 'undefined') {
    document.addEventListener('DOMContentLoaded', function() {
        var productData = {
            product_id: {{ product_id }},
            {% if options %}
            options: {{ options|json_encode|raw }},
            {% endif %}
            quantity_selector: '#product-quantity, #input-quantity',
            price_element: '#product .price-new, #product .price',
            currency: '{{ currency_code }}',
            ajax_url: 'index.php?route=extension/module/stripe_product_payment/process'
        };

        StripeProductApplePay.init(productData);
    });
}
</script>
{% endif %}
